        (c_bi == NULL) || (primary_index == NULL) || (geometry_quality == NULL)) {
        return ADCS_E_NULL;
    }

    if ((!isfinite(variance_a)) || (variance_a <= 0.0) ||
        (!isfinite(variance_b)) || (variance_b <= 0.0)) {
        return ADCS_E_RANGE;
    }

    adcs_vec3_t ref_a_norm, ref_b_norm;
    if (adcs_vec3_normalize(ref_a, ADCS_EPS_NORM, &ref_a_norm) != ADCS_OK) {
        return ADCS_E_RANGE;
    }
    if (adcs_vec3_normalize(ref_b, ADCS_EPS_NORM, &ref_b_norm) != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    double dot_ref = adcs_vec3_dot(&ref_a_norm, &ref_b_norm);
    double sin_sq = 1.0 - dot_ref * dot_ref;
    if (sin_sq < 0.0) {
        sin_sq = 0.0;
    }
    double sin_sep = sqrt(sin_sq);

    if (sin_sep <= ADCS_EPS_COLLINEAR) {
        return ADCS_E_DEGENERATE;
    }

    int p_idx = 0;
    if (variance_a > variance_b) {
        p_idx = 1;
    }
    *primary_index = p_idx;

    double selected_variance = (p_idx == 0) ? variance_a : variance_b;
    *geometry_quality = sin_sep / selected_variance;

    adcs_status_t triad_status = ADCS_OK;
    if (p_idx == 0) {
        triad_status = adcs_triad(body_a, body_b, &ref_a_norm, &ref_b_norm, c_bi);
    } else {
        triad_status = adcs_triad(body_b, body_a, &ref_b_norm, &ref_a_norm, c_bi);
    }

    if (triad_status != ADCS_OK) {
        return triad_status;
    }

    return ADCS_OK;
}

